net.rptools.maptool.model.MacroButtonPro.command:
[h, if(getInitiativeToken() == currentToken()), code: 
{ 
	[message = add(token.name, " ends ", PronounPossessive, " turn.")] 
	[broadcast(message)] 
	[nextInitiative()]
}; 
{
	[message = add("<i style='color:gray;'>It is not ", token.name, "'s turn!</i>")]
	[broadcast(message, getPlayerName(), "gm")]
};]

/me attempts a Sleight of Hand
 check! ([t: 1d20 + DexMod + (Proficiency * SleightOfHand
)])

/me attempts a Stealth
 check! ([t: 1d20 + DexMod + (Proficiency * Stealth
)])

[h: initToken = getInitiativeToken()]
[h: thisToken = currentToken()]
[h, if(initToken == thisToken), code: { 
	[if(ReadyAction == ""), code: {
		[input("trigger|enemies come in range|What trigger will you react to?|TEXT",
	"action|I use my attack action|What action will you take?|TEXT")]
		[ActionDescription = "When " + trigger + ", " + action]
		[ReadyAction = ActionDescription]
		[message = add(token.name, 
						" has readied an action: <i>", 
						ReadyAction, 
						"</i>")] 
		[broadcast(message)] 
		[setInitiativeHold(1)]
	};
	{
		[message = add(token.name, 
						" unreadies their action. (<i>", 
						ReadyAction, 
						"</i>)")] 
		[broadcast(message)] 
		[setInitiativeHold(0)]
		[ReadyAction = ""]
	};]
};
{
	[if(getInitiativeHold() == 1), code: {
		[message = add(token.name, 
						" triggers their readied action! (<i>", 
						ReadyAction, 
						"</i>)")] 
		[broadcast(message)] 
		[setInitiativeHold(0)]
		[ReadyAction = ""]
	};
	{
		[message = add("<i style='color:gray;'>",
						token.name,
						" clears any readied action.</i>")]
		[broadcast(message, getPlayerName())]
		[ReadyAction = ""]
	};]
};]

/me
[if(state.Dodging == 1), CODE:
{
     [h:state.Dodging=0]
     is no longer dodging.
};
{
     [h:state.Dodging=1]
uses Dodge:
<br>&nbsp;&nbsp;&nbsp;• Attackers [r: token.name] is aware of have disadvantage on their attacks against [r: PronounObjective].
<br>&nbsp;&nbsp;&nbsp;• [r: upper(PronounSubjective, 1)] gets advantage on Dexterity saving throws. 
<br>&nbsp;&nbsp;&nbsp;• This benefit is lost if [r: token.name] is incapacitated or [r: PronounPossessive] speed is dropped to 0.
}]

/me 
[h: "<!-- Make sure the character is actually dying. -->"]
[h, if(HP > 0 || state.Stable == 1), code: {
	[vErrorMsgA = if(HP > 0, "You aren't at 0 HP,", "You are <b>Stable</b>.")]
	[vErrorMsgB = if(HP > 0, "set your HP to 0", "remove the <b>Stable</b> condition")]
	[vInput = input("header | <html><h2 align='center'>You aren't dying!</h2><p align=center>" + vErrorMsgA + "</p><br><hr><p>- Hit 'OK' to " + vErrorMsgB + " and continue.<br>- Hit 'Cancel' to leave your HP as it is.</p></html> | | LABEL | SPAN=TRUE")]
	[abort(vInput)]
	[HP = 0]
}]

[h: "<!-- Ensure the 'Dying' state is set and roll a save. -->"]
[h: state.Stable = 0]
[h: state.Dying = 1]
[h: vSaveRoll = 1d20]

[h: "<!-- Check if the character passed the roll. -->"]
[r, if(vSaveRoll < 10), code: {
	[h, if(vSaveRoll > 1): DeathFails = DeathFails + 1; DeathFails = DeathFails + 2]
	[h, if(DeathFails > 3): DeathFails = 3]
	[r: "<b style='color:red'>" + if(vSaveRoll == 1, "CRITICALLY ", "") + "FAILS</b> a death save (" + vSaveRoll + "). That's " + DeathFails + " of 3..."]
	[if(DeathFails >= 3): broadcast("<i style='color:red'><b>GM ALERT</b>: " + token.name + " has technically died...</i>", "gm")]	
};
{
	[r, if(vSaveRoll >= 10 && vSaveRoll < 20), code: {
		[h: "<!-- On a non-critical success, add a Death Success. -->"]
		[h: DeathSuccesses = DeathSuccesses + 1]
		[r: "<b style='color:blue'>PASSES</b> a death save (" + vSaveRoll + "). That's " + DeathSuccesses + " of 3 needed to stabilize... "]		
	};
	{
		[h: "<!-- On a critical success, give award 1hp! -->"]
		[r: "<b style='color:blue'>CRITICALLY PASSES</b> a death save (" + vSaveRoll + "), instantly regaining 1 hit point!"]
		[h: DeathFails = ""]
		[h: DeathSuccesses = ""]
		[h: state.Dead = 0]
		[h: state.Dying = 0]		
		[h: HP = HP + 1]
	}]
}]

[r, if(number(DeathSuccesses) >= 3), code: { 
	[r: token.name + " has stabilized!"]
	[h: DeathFails = ""]
	[h: DeathSuccesses = ""]
	[h: state.Dead = 0]
	[h: state.Dying = 0]
	[h, if(HP == 0): state.Stable = 1]
}]

[h: "<!-- Perform bar logic. -->"]
[h, if(HP < eMaxHP): setBarVisible("Health (Approximate)", 0)]
[h, if(HP < eMaxHP): setBar("Health", eHP / eMaxHP); setBarVisible("Health", 0)]

[h: "<!-- Reload Character Sheet if present. -->"]
[h, if(isFrameVisible(token.name + " - Character Sheet") && hasMacro("Sheet")), code: {
	[macro("Sheet@this"):""]
};{}]

/me 
[r, if(state.AFK == 0), code: {
	[h: state.AFK = 1]
	([r: getPlayerName()]) has gone AFK.

};{
	[h: state.AFK = 0]
	([r: getPlayerName()]) is back from AFK.

}]

/me
[h: "<!-- If not concentrating, let player set concentration. -->"]
[h, if(state.Concentrating == 0), code: {
	[vInput = input( "header | <html><h2 style='width:150px;text-align:center;'>You're not<br>concentrating.</h2><br><hr> | | LABEL | SPAN=TRUE",
	"header | Enter what to concentrate on: || LABEL | SPAN=TRUE",
	"Concentration | " + if(length(Concentration) > 0, Concentration, PronounPossessive + " spell") + 
		" || TEXT | SPAN=TRUE WIDTH=24", 
	"vDoRoll | 1 | Immediately roll saving throw | CHECK |")]
	[abort(vInput)]
	[state.Concentrating = 1]
};{ 
	[vDoRoll = 1] 
}]

[h, if(vDoRoll), code: {
	[abort(input("vDamage|0|Enter damage to save against|TEXT|WIDTH=4", "vAutoFail | 0 | Check to stop concentrating | CHECK"))]
	[if(vAutoFail), code:{
		[vGrammarHelper = " on "]
		[if(Concentration == ""): vGrammarHelper = ""]
		[vMsg = "stops concentrating" + vGrammarHelper + Concentration + "."]
		[state.Concentrating = 0]
		[resetProperty("Concentration")]
	};{}]
};{
	[vGrammarHelper = " on "]
	[if(Concentration == ""): vGrammarHelper = ""]
	[vMsg = "is concentrating" + vGrammarHelper + Concentration + "."]
	[vAutoFail = 0]
}]

[h, if(vDoRoll && !vAutoFail), code: {
	[h, if(vDamage < 0): vDamage = 0]
	[vSaveDC = floor(vDamage / 2)]
	[if(vSaveDC < 11): vSaveDC = 10]
	[vSaveRoll = 1d20]
	[vSaveTotal = vSaveRoll + ConMod + (ConSave * Proficiency)]
	[vSaveToolTip = "(<span style='background-color:#efefef' " + 
		"title='1d20 + ConMod + (ConSave * Proficiency) = " +
		vSaveRoll + " + " + ConMod + " + " + ConSave + " * " + Proficiency + " = " +
		vSaveTotal + "'>" + vSaveTotal + " vs DC " + vSaveDC + "</span>)"]
	[vGrammarHelper = " on "]
	[if(Concentration == ""): vGrammarHelper = ""]
	[if(vSaveTotal >= vSaveDC), code: {
		[vMsg = " <b>maintains concentration</b>" + 
			vGrammarHelper + Concentration + ". " + vSaveToolTip]
	};{
		[vMsg = "<b style='color:red;'>" + " loses concentration</b>" + 
		vGrammarHelper + Concentration + "! " + 
			vSaveToolTip]
		[state.Concentrating = 0]
		[resetProperty("Concentration")]
	}]
};{}]

[r: vMsg]
